/* ============================================================
   PROJECT  : ODI CRICKET PLAYER PERFORMANCE ANALYSIS
   DATABASE : Microsoft SQL Server
   SOURCE   : Cricsheet.csv
   RECORDS  : 1,540 players
   ============================================================ */

IF DB_ID(N'ODI_Cricket_Performance_DB') IS NULL
BEGIN
    CREATE DATABASE ODI_Cricket_Performance_DB;
END;
GO

USE ODI_Cricket_Performance_DB;
GO

IF OBJECT_ID(N'dbo.cricsheet', N'U') IS NOT NULL
    DROP TABLE dbo.cricsheet;
GO

CREATE TABLE dbo.cricsheet
(
    player_name                 NVARCHAR(150) NOT NULL,
    role                        NVARCHAR(50)  NOT NULL,
    total_runs                  INT           NOT NULL,
    strike_rate                 DECIMAL(10,6) NOT NULL,
    total_balls_faced           INT           NOT NULL,
    total_wickets_taken         INT           NOT NULL,
    total_runs_conceded         INT           NOT NULL,
    total_overs_bowled          INT           NOT NULL,
    total_matches_played        INT           NOT NULL,
    matches_played_as_batter    INT           NOT NULL,
    matches_played_as_bowler    INT           NOT NULL,
    matches_won                 INT           NOT NULL,
    matches_lost                INT           NOT NULL,
    player_of_match_awards      INT           NOT NULL,
    team                        NVARCHAR(100) NOT NULL,
    average                     DECIMAL(12,6) NULL
);
GO

/* ============================================================
   DATA INSERT
   ============================================================ */

GO

GO

GO

GO

/* ============================================================
   VERIFICATION QUERIES
   ============================================================ */

SELECT COUNT(*) AS Total_Records
FROM dbo.cricsheet;

SELECT TOP 10 *
FROM dbo.cricsheet
ORDER BY total_runs DESC;

SELECT
    COUNT(DISTINCT player_name) AS Total_Players,
    SUM(total_runs) AS Total_Runs,
    SUM(total_wickets_taken) AS Total_Wickets,
    SUM(total_matches_played) AS Total_Matches
FROM dbo.cricsheet;
GO
